"""Inject the BARAKA Invest favicon (browser-tab icon) into dist/index.html.

The site ships as a single self-contained file, so the icon is embedded as
data URIs rather than served as a separate /favicon.ico. Icons are rendered
from the site's own logo mark. Also sets the mobile browser theme colour to
the brand blue.
"""
import json
import re

ICON32 = ""
ICON180 = ""

FAVICON = (
    '  <link rel="icon" type="image/png" sizes="32x32" href="data:image/png;base64,'
    + ICON32
    + '">\n'
    '  <link rel="apple-touch-icon" sizes="180x180" href="data:image/png;base64,'
    + ICON180
    + '">\n'
    '  <meta name="theme-color" content="#00348C">\n'
)

path = "dist/index.html"
src = open(path).read()
m = re.search(r'(<script type="__bundler/template">\s*)(.*?)(\s*</script>)', src, re.S)
tpl = json.loads(m.group(2))
assert 'rel="icon"' not in tpl, "favicon already present"

marker = "</style>\n</helmet>"
assert marker in tpl, "helmet closing marker not found"
tpl = tpl.replace(marker, "</style>\n" + FAVICON + "</helmet>", 1)

encoded = json.dumps(tpl).replace("</", "<\\/")
out = src[: m.start(2)] + encoded + src[m.end(2) :]
open(path, "w").write(out)
print("injected favicon; dist/index.html now", len(out), "bytes")
